import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, color, smoothstep, float, vec3, fract, sin } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, DoubleSide } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'features-card-2-label';

  const inner = new Group();
  root.add(inner);

  // --- engineered gradient card backdrop (with grain + accent underline stripe) ---
  const cardW = 1.6;
  const cardH = 0.56;
  const cardGeo = new PlaneGeometry(cardW, cardH);

  const uvNode = uv();
  const topColor = color(colors.ink);
  const bottomColor = color(colors.surface);
  const grain = fract(sin(uvNode.x.mul(93.17).add(uvNode.y.mul(41.31))).mul(43758.5453))
    .sub(0.5)
    .mul(0.035);
  const baseGrad = mix(topColor, bottomColor, uvNode.y).add(vec3(grain, grain, grain));
  const stripe = smoothstep(float(0.0), float(0.06), uvNode.y).oneMinus();
  const accentColor = color(colors.accent);
  const finalColor = mix(baseGrad, accentColor, stripe.mul(0.9));

  const cardMat = new MeshBasicNodeMaterial();
  cardMat.colorNode = finalColor;
  cardMat.transparent = true;
  cardMat.opacity = 0;
  cardMat.side = DoubleSide;

  const cardMesh = new Mesh(cardGeo, cardMat);
  inner.add(cardMesh);

  // --- decorative orb image, subtle accent decoration, top-right corner ---
  const decorSize = 0.38;
  const decorGeo = new PlaneGeometry(decorSize, decorSize);
  const decorMat = new MeshBasicNodeMaterial();
  decorMat.transparent = true;
  decorMat.opacity = 0;
  decorMat.depthWrite = false;
  const decorMesh = new Mesh(decorGeo, decorMat);
  decorMesh.position.set(cardW / 2 - decorSize * 0.55, cardH / 2 - decorSize * 0.55, 0.01);
  inner.add(decorMesh);

  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        decorMat.map = tex;
        decorMat.needsUpdate = true;
      })
      .catch(() => {});
  }

  // --- headline text: "Features 2" ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem =
    items.find((i) => i.role === 'headline') ??
    items[0] ?? { text: 'Features 2', role: 'headline', typography: { fontSize: 39 } };
  const fontSize = headlineItem?.typography?.fontSize ?? 39;

  const textObj = ctx.fontAtlas.createText(headlineItem?.text ?? 'Features 2', {
    fontSize,
    color: colors.paper,
    align: 'left',
  });
  textObj.position.set(-cardW / 2 + 0.14, -0.03, 0.02);
  inner.add(textObj);

  const setOpacityRecursive = (obj, val) => {
    obj.traverse?.((n) => {
      if (n.material) {
        const mats = Array.isArray(n.material) ? n.material : [n.material];
        mats.forEach((m) => {
          m.transparent = true;
          m.opacity = val;
        });
      }
    });
  };
  setOpacityRecursive(textObj, 0);

  // --- apply any configured cinematic primitives (contract compliance; none listed for this node) ---
  const primitiveHandles = [];
  const primitiveList = config.cinematicPrimitives ?? [];
  for (const prim of primitiveList) {
    const fn = ctx.primitives?.[prim.name];
    if (typeof fn === 'function') {
      const handle = fn(inner, prim.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // --- weighted-settle entrance (local wrapper transform only; root transform owned by adapter) ---
  inner.position.y = 0.14;
  const fadeState = { v: 0 };
  const tl = gsap.timeline();
  tl.to(inner.position, { y: 0, duration: 0.9, ease: 'power4.out' }, 0);
  tl.to(cardMat, { opacity: 1, duration: 0.6, ease: 'power2.out' }, 0.05);
  tl.to(decorMat, { opacity: 0.28, duration: 0.7, ease: 'power2.out' }, 0.18);
  tl.to(
    fadeState,
    {
      v: 1,
      duration: 0.6,
      ease: 'power2.out',
      onUpdate() {
        setOpacityRecursive(textObj, fadeState.v);
      },
    },
    0.15
  );

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    tl.kill();
    primitiveHandles.forEach((h) => h.cleanup?.());
    cardGeo.dispose();
    cardMat.dispose();
    decorGeo.dispose();
    if (decorMat.map) decorMat.map.dispose?.();
    decorMat.dispose();
    textObj.traverse?.((n) => {
      n.geometry?.dispose?.();
      if (n.material) {
        const mats = Array.isArray(n.material) ? n.material : [n.material];
        mats.forEach((m) => m.dispose?.());
      }
    });
  };

  return root;
}
